import{_ as i,o as n,c as t,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Konstitusi Peradaban Simbiosis","description":"","frontmatter":{},"headers":[],"relativePath":"id/03-共生文明宪章.md","filePath":"id/03-共生文明宪章.md"}'),e={name:"id/03-共生文明宪章.md"};function r(u,a,d,k,o,m){return n(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="konstitusi-peradaban-simbiosis" tabindex="-1">Konstitusi Peradaban Simbiosis <a class="header-anchor" href="#konstitusi-peradaban-simbiosis" aria-label="Permalink to &quot;Konstitusi Peradaban Simbiosis&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>03</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Konstitusi, Hukum Dasar, Sistem Simbiosis, Republik Sepuluh Ribu Ras, Hak dan Kewajiban</td></tr></tbody></table><h2 id="i-kedudukan-dan-sifat-konstitusi" tabindex="-1">I. Kedudukan dan Sifat Konstitusi <a class="header-anchor" href="#i-kedudukan-dan-sifat-konstitusi" aria-label="Permalink to &quot;I. Kedudukan dan Sifat Konstitusi&quot;">​</a></h2><p>Konstitusi Peradaban Simbiosis adalah hukum dasar dari Peradaban Simbiosis Jangkar di Kosmos Asli dari Sepuluh Ribu Roh dan Jangkar Seimbang, dan merupakan dasar tertinggi dari semua hukum, institusi, dan kebijakan. Konstitusi mengambil &quot;Deklarasi Peradaban Simbiosis Jangkar&quot; sebagai pelopor spiritualnya, dan mewujudkan klaim inti deklarasi menjadi norma hukum yang mengikat. Kekuatan konstitusi mencakup semua ras, bidang, dan individu yang bergabung dengan peradaban simbiosis di Heng Yuan Zhou, dan peraturan lokal, aturan sekte, atau adat ras apa pun yang bertentangan dengan konstitusi adalah tidak sah.</p><p>Sifat konstitusi dapat diringkas dalam tiga poin: pertama, ia adalah kontrak peradaban, yaitu kesepakatan dasar yang dicapai di antara Sepuluh Ribu Ras mengenai evolusi simbiosis; kedua, ia adalah piagam jaminan hak, yang secara jelas menetapkan hak dan kebebasan dasar setiap makhluk dalam peradaban simbiosis; dan ketiga, ia adalah hukum pembatasan kekuasaan, yang menetapkan batas yang tidak dapat dilampaui untuk kekuasaan institusi pemerintahan peradaban.</p><h2 id="ii-prinsip-dasar-konstitusi" tabindex="-1">II. Prinsip Dasar Konstitusi <a class="header-anchor" href="#ii-prinsip-dasar-konstitusi" aria-label="Permalink to &quot;II. Prinsip Dasar Konstitusi&quot;">​</a></h2><p>Konstitusi menetapkan enam prinsip dasar berikut, yang meresap ke dalam semua pasal:</p><ol><li><strong>Prinsip Supremasi Simbiosis</strong>: tujuan tertinggi dari setiap desain institusional dan pelaksanaan kekuasaan adalah mempromosikan evolusi simbiosis Sepuluh Ribu Ras. Ketika kepentingan individu bertentangan dengan kepentingan simbiosis kolektif, kepentingan simbiosis diutamakan, tetapi individu harus diberikan kompensasi yang wajar dan jalur alternatif.</li><li><strong>Prinsip Anti-Predasi</strong>: konstitusi melarang semua bentuk perilaku predator, termasuk tetapi tidak terbatas pada predasi energi, pemangsaan asal, perbudakan spiritual, dan monopoli sumber daya. Sistem kultivasi apa pun yang berpusat pada predasi dinyatakan ilegal.</li><li><strong>Prinsip Kesetaraan Hak Evolusi</strong>: semua makhluk setara di hadapan hak evolusi, tanpa diskriminasi karena ras, bentuk, asal-usul, atau tingkat kultivasi awal. Negara dan peradaban berkewajiban memberikan dukungan evolusi tambahan bagi kelompok rentan.</li><li><strong>Prinsip Lebih Banyak Kerja, Lebih Banyak Imbalan</strong>: distribusi sumber daya evolusi didasarkan terutama pada kontribusi individu terhadap jaringan simbiosis; semakin besar kontribusi, semakin banyak sumber daya dan dukungan yang diterima. Pada saat yang sama, garis jaminan dasar ditetapkan, memastikan bahwa bahkan individu dengan kontribusi lebih kecil dapat memperoleh kondisi evolusi dasar.</li><li><strong>Prinsip Kombinasi Otonomi dan Pemerintahan Bersama</strong>: setiap ras menikmati otonomi dalam urusan internalnya selama tidak melanggar konstitusi; urusan publik antar-ras dan antar-bidang diatur bersama oleh institusi Republik Sepuluh Ribu Ras.</li><li><strong>Prinsip Realitas sebagai Dasar</strong>: semua desain institusional konstitusi memiliki dunia nyata sebagai satu-satunya dasar nyata; tidak diakui bahwa hubungan hak dan kewajiban apa pun di dunia fiktif dapat ditumpangkan pada realitas.</li></ol><h2 id="iii-struktur-dasar-konstitusi" tabindex="-1">III. Struktur Dasar Konstitusi <a class="header-anchor" href="#iii-struktur-dasar-konstitusi" aria-label="Permalink to &quot;III. Struktur Dasar Konstitusi&quot;">​</a></h2><p>Konstitusi terdiri dari enam bagian: pembukaan, prinsip umum, hak dan kewajiban dasar, institusi peradaban, sistem hukum, dan proses revisi:</p><table tabindex="0"><thead><tr><th>Bagian</th><th>Isi Inti</th><th>Jumlah Pasal</th></tr></thead><tbody><tr><td>Pembukaan</td><td>Menjelaskan latar belakang sejarah, sumber spiritual, dan tujuan utama konstitusi</td><td>Tidak bernomor</td></tr><tr><td>Prinsip Umum</td><td>Menetapkan sifat peradaban, pandangan kosmik, institusi inti, dan kebijakan dasar</td><td>30 pasal</td></tr><tr><td>Hak dan Kewajiban Dasar</td><td>Menetapkan hak-hak dasar makhluk, seperti hak evolusi, hak informasi, hak partisipasi, dan kewajiban yang sesuai</td><td>50 pasal</td></tr><tr><td>Institusi Peradaban</td><td>Menetapkan organisasi dan wewenang institusi seperti Parlemen Republik Sepuluh Ribu Ras, Komite Eksekutif Simbiosis, dan Pengadilan Jangkar</td><td>40 pasal</td></tr><tr><td>Sistem Hukum</td><td>Menetapkan wewenang legislatif dan aturan penerapan hukum perburuhan, hukum perlindungan konsumen, dan lima hukum pelengkap di bawah konstitusi</td><td>20 pasal</td></tr><tr><td>Proses Revisi</td><td>Menetapkan proses proposal, pembahasan, pemungutan suara, dan pemberlakuan revisi konstitusi</td><td>10 pasal</td></tr></tbody></table><h2 id="iv-hak-dan-kewajiban-dasar" tabindex="-1">IV. Hak dan Kewajiban Dasar <a class="header-anchor" href="#iv-hak-dan-kewajiban-dasar" aria-label="Permalink to &quot;IV. Hak dan Kewajiban Dasar&quot;">​</a></h2><p>Hak-hak dasar inti yang ditetapkan oleh konstitusi meliputi:</p><ul><li><strong>Hak Pilihan Evolusi</strong>: setiap makhluk berhak memilih secara bebas sistem kultivasi dan jalur evolusinya, tidak ada yang boleh memaksa</li><li><strong>Hak Akses Sistem</strong>: setiap makhluk berhak mengakses secara gratis metode dasar dari Tiga Ratus Sistem Kultivasi Asal</li><li><strong>Hak Distribusi Sumber Daya</strong>: setiap makhluk berhak memperoleh sumber daya kultivasi dasar melalui sistem kontrak berbasis produksi</li><li><strong>Hak Koneksi Jangkar</strong>: setiap makhluk yang mencapai tingkat tertentu berhak terhubung ke jaringan titik jangkar dari tingkat yang sesuai</li><li><strong>Hak Informasi dan Partisipasi</strong>: setiap makhluk berhak mengetahui urusan publik peradaban dan berpartisipasi dalam pengambilan keputusan</li><li><strong>Hak Pemulihan dan Pengaduan</strong>: setiap makhluk, ketika haknya dilanggar, berhak mengajukan pengaduan ke Pengadilan Jangkar</li></ul><p>Kewajiban inti yang sesuai meliputi: mematuhi prinsip anti-predasi, menjaga stabilitas jaringan titik jangkar, berpartisipasi dalam siklus umpan balik simbiosis, mewariskan pengetahuan kultivasi, melindungi ekosistem kosmik.</p><h2 id="v-revisi-dan-jaminan-konstitusi" tabindex="-1">V. Revisi dan Jaminan Konstitusi <a class="header-anchor" href="#v-revisi-dan-jaminan-konstitusi" aria-label="Permalink to &quot;V. Revisi dan Jaminan Konstitusi&quot;">​</a></h2><p>Revisi konstitusi memerlukan proposal bersama dari lebih dari seperlima anggota Parlemen Republik Sepuluh Ribu Ras, disetujui oleh mayoritas dua pertiga parlemen, dan diverifikasi oleh Titik Jangkar Asal Kosmik bahwa tidak melanggar hukum simbiosis — baru kemudian berlaku. Kekuatan interpretasi konstitusi dimiliki oleh Pengadilan Jangkar.</p><p>Untuk menjamin implementasi konstitusi, peradaban simbiosis telah menetapkan sistem peninjauan konstitusional: hukum, peraturan, atau kebijakan apa pun harus melalui peninjauan konstitusionalitas Pengadilan Jangkar sebelum berlaku; makhluk apa pun yang menganggap tindakan kekuasaan publik tidak konstitusional dapat mengajukan gugatan konstitusional.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Konstitusi Peradaban Simbiosis adalah batu penjuru institusional dari Peradaban Simbiosis Jangkar. Ia mengubah ide &quot;anti-predasi, mempromosikan simbiosis&quot; menjadi norma hukum yang dapat dilaksanakan, dipulihkan, dan diawasi, memberikan jaminan institusional yang kokoh untuk kemajuan bersama Sepuluh Ribu Ras. Konstitusi bukanlah dogma yang tidak berubah, melainkan hukum dasar yang hidup yang terus disempurnakan seiring dengan evolusi peradaban.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Deklarasi Peradaban Simbiosis Jangkar)</li><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>49-治理框架与权力制衡 (Kerangka Pemerintahan dan Keseimbangan Kekuasaan)</li></ul>',22)])])}const b=i(e,[["render",r]]);export{p as __pageData,b as default};
